agent_base_units.command:
cd $(git rev-parse --show-toplevel) && python3 - <<'EOF'
p='error_handling_test.go'
s=open(p).read()
anchor='''	// Using retry outside a catch block raises a runtime error.
	err = mustErr(t, `retry`, nil)
	require.Contains(t, err.Error(), "retry")
}'''
add='''	// Using retry outside a catch block raises a runtime error.
	err = mustErr(t, `retry`, nil)
	require.Contains(t, err.Error(), "retry")
}

func TestRetryLimit(t *testing.T) {
	// Exactly three retries are allowed before exhaustion.
	var counter int
	env := map[string]any{
		"counter": &counter,
		"fail": func() any {
			counter++
			if counter < 4 {
				panic("not yet")
			}
			return counter
		},
	}
	require.Equal(t, 4, mustRun(t, `try { fail() } catch { retry }`, env))
	require.Equal(t, 4, counter)

	// A fourth retry is rejected with a distinct retry error.
	counter = 0
	env["fail"] = func() any {
		counter++
		if counter < 5 {
			panic("not yet")
		}
		return counter
	}
	err := mustErr(t, `try { fail() } catch { retry }`, env)
	require.Contains(t, err.Error(), "retry")
	require.Equal(t, 4, counter)
}'''
assert anchor in s
s=s.replace(anchor, add)

anchor='''	// Uncaught throw propagates out of the expression.
	err = mustErr(t, `throw("boom")`, nil)
	require.Contains(t, err.Error(), "boom")
}'''
add='''	// Uncaught throw propagates out of the expression.
	err = mustErr(t, `throw("boom")`, nil)
	require.Contains(t, err.Error(), "boom")

	// throw(e) of a caught error still produces a custom error.
	out = mustRun(t, `try { try { throw("a") } catch e { throw(e) } } catch e2 { errtype(e2) }`, nil)
	require.Equal(t, "custom", out)
}'''
assert anchor in s
s=s.replace(anchor, add)
open(p,'w').write(s)
print("done")
EOF
go test -run 'TestRetry|TestThrow|TestErrType|TestTry|TestCatch|TestFinally' . 2>&1 | head -40
